package com.jeshwin.crashlab;
import java.util.Properties;import java.util.concurrent.TimeUnit;import org.apache.kafka.clients.producer.*;import org.apache.kafka.common.serialization.StringSerializer;
public final class M3Producer {private M3Producer(){} public static void main(String[]a)throws Exception{if(a.length!=3)throw new IllegalArgumentException("topic eventId accountId");Properties p=new Properties();p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,LabConfig.kafkaBootstrap());p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class.getName());p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,StringSerializer.class.getName());try(var x=new KafkaProducer<String,String>(p)){var m=x.send(new ProducerRecord<>(a[0],a[1],a[2]+"|100")).get(20,TimeUnit.SECONDS);x.flush();System.out.println("{\"partition\":"+m.partition()+",\"offset\":"+m.offset()+"}");}}}
